# True when ``items`` is a one-dimensional list of 1 to ``max_items`` items,
# each holding something besides blanks and at most ``max_chars`` characters.
# Never NULL, which a check would let pass: an empty array has no dimensions.
ITEMS_SQL = r"""
CREATE OR REPLACE FUNCTION report_items_valid(items text[], max_items integer, max_chars integer)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT coalesce(array_ndims(items), 0) = 1
    AND cardinality(items) <= max_items
    AND NOT EXISTS (
      SELECT 1 FROM unnest(items) AS item
      WHERE item IS NULL OR item !~ '\S' OR char_length(item) > max_chars
    )
$$;
"""

